-- Generated by python -m migrations.bootstrap; review model + Alembic changes together.

-- Empty-schema bootstrap only. Existing installations require an isolated schema comparison

-- and reviewed Alembic adoption; IF NOT EXISTS never repairs existing column/index drift.

-- No alembic stamp is implied by this file; no live database is contacted by the generator.

BEGIN;

CREATE TABLE IF NOT EXISTS batches (
	batch_id UUID NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	version INTEGER NOT NULL, 
	metadata_json JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (batch_id)
);

CREATE INDEX IF NOT EXISTS ix_batches_created_at ON batches (created_at);

CREATE INDEX IF NOT EXISTS ix_batches_status ON batches (status);

CREATE TABLE IF NOT EXISTS checklist_types (
	checklist_type VARCHAR(100) NOT NULL, 
	checklist_name VARCHAR(255) NOT NULL, 
	description TEXT, 
	is_active BOOLEAN NOT NULL, 
	sort_order INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (checklist_type)
);

CREATE INDEX IF NOT EXISTS ix_checklist_types_is_active ON checklist_types (is_active);

CREATE TABLE IF NOT EXISTS document_artifacts (
	artifact_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	file_hash VARCHAR(64) NOT NULL, 
	preprocess_profile_version VARCHAR(50) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	pages JSON NOT NULL, 
	quality JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (artifact_id)
);

CREATE INDEX IF NOT EXISTS ix_document_artifacts_created_at ON document_artifacts (created_at);

CREATE INDEX IF NOT EXISTS ix_document_artifacts_document_id ON document_artifacts (document_id);

CREATE INDEX IF NOT EXISTS ix_document_artifacts_file_hash ON document_artifacts (file_hash);

CREATE INDEX IF NOT EXISTS ix_document_artifacts_preprocess_profile_version ON document_artifacts (preprocess_profile_version);

CREATE INDEX IF NOT EXISTS ix_document_artifacts_status ON document_artifacts (status);

CREATE TABLE IF NOT EXISTS document_context_audits (
	audit_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	context_id UUID, 
	action VARCHAR(30) NOT NULL, 
	before JSON, 
	after JSON, 
	actor VARCHAR(100) NOT NULL, 
	reason TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (audit_id)
);

CREATE INDEX IF NOT EXISTS ix_document_context_audits_context_id ON document_context_audits (context_id);

CREATE INDEX IF NOT EXISTS ix_document_context_audits_created_at ON document_context_audits (created_at);

CREATE INDEX IF NOT EXISTS ix_document_context_audits_document_id ON document_context_audits (document_id);

CREATE TABLE IF NOT EXISTS document_contexts (
	context_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	subtype VARCHAR(30) NOT NULL, 
	context JSON NOT NULL, 
	revision INTEGER NOT NULL, 
	actor VARCHAR(100) NOT NULL, 
	reason TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (context_id), 
	CONSTRAINT uq_document_context_revision UNIQUE (document_id, revision)
);

CREATE INDEX IF NOT EXISTS ix_document_contexts_created_at ON document_contexts (created_at);

CREATE INDEX IF NOT EXISTS ix_document_contexts_document_id ON document_contexts (document_id);

CREATE INDEX IF NOT EXISTS ix_document_contexts_subtype ON document_contexts (subtype);

CREATE TABLE IF NOT EXISTS document_relation_audits (
	audit_id UUID NOT NULL, 
	relation_id UUID, 
	source_document_id UUID NOT NULL, 
	target_document_id UUID NOT NULL, 
	action VARCHAR(30) NOT NULL, 
	revision INTEGER NOT NULL, 
	snapshot JSON, 
	actor VARCHAR(100) NOT NULL, 
	reason TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (audit_id), 
	CONSTRAINT uq_document_relation_revision UNIQUE (source_document_id, revision)
);

CREATE INDEX IF NOT EXISTS ix_document_relation_audits_created_at ON document_relation_audits (created_at);

CREATE INDEX IF NOT EXISTS ix_document_relation_audits_relation_id ON document_relation_audits (relation_id);

CREATE INDEX IF NOT EXISTS ix_document_relation_audits_source_document_id ON document_relation_audits (source_document_id);

CREATE INDEX IF NOT EXISTS ix_document_relation_audits_target_document_id ON document_relation_audits (target_document_id);

CREATE TABLE IF NOT EXISTS document_relations (
	relation_id UUID NOT NULL, 
	source_document_id UUID NOT NULL, 
	target_document_id UUID NOT NULL, 
	source_role VARCHAR(30) NOT NULL, 
	relation_type VARCHAR(40) NOT NULL, 
	actor VARCHAR(100) NOT NULL, 
	reason TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (relation_id), 
	CONSTRAINT uq_document_relation_pair UNIQUE (source_document_id, target_document_id)
);

CREATE INDEX IF NOT EXISTS ix_document_relations_created_at ON document_relations (created_at);

CREATE INDEX IF NOT EXISTS ix_document_relations_source_document_id ON document_relations (source_document_id);

CREATE INDEX IF NOT EXISTS ix_document_relations_target_document_id ON document_relations (target_document_id);

CREATE TABLE IF NOT EXISTS documents (
	document_id UUID NOT NULL, 
	file_name VARCHAR(500) NOT NULL, 
	original_name VARCHAR(500) NOT NULL, 
	file_path TEXT NOT NULL, 
	file_size BIGINT NOT NULL, 
	file_hash VARCHAR(64) NOT NULL, 
	mime_type VARCHAR(100) NOT NULL, 
	mine_id VARCHAR(100), 
	mine_name VARCHAR(200), 
	checklist_type VARCHAR(100), 
	report_period VARCHAR(50), 
	page_count INTEGER, 
	parse_status VARCHAR(50) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (document_id)
);

CREATE INDEX IF NOT EXISTS ix_documents_checklist_type ON documents (checklist_type);

CREATE INDEX IF NOT EXISTS ix_documents_created_at ON documents (created_at);

CREATE INDEX IF NOT EXISTS ix_documents_file_hash ON documents (file_hash);

CREATE INDEX IF NOT EXISTS ix_documents_mine_id ON documents (mine_id);

CREATE INDEX IF NOT EXISTS ix_documents_parse_status ON documents (parse_status);

CREATE INDEX IF NOT EXISTS ix_documents_report_period ON documents (report_period);

CREATE TABLE IF NOT EXISTS execution_outbox (
	event_id UUID NOT NULL, 
	kind VARCHAR(100) NOT NULL, 
	aggregate_id UUID NOT NULL, 
	dedupe_key VARCHAR(500) NOT NULL, 
	payload JSON NOT NULL, 
	dispatch_state VARCHAR(32) NOT NULL, 
	next_attempt_at TIMESTAMP WITHOUT TIME ZONE, 
	attempts INTEGER NOT NULL, 
	last_error TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (event_id), 
	CONSTRAINT uq_execution_outbox_kind_dedupe UNIQUE (kind, dedupe_key)
);

CREATE INDEX IF NOT EXISTS ix_execution_outbox_aggregate_id ON execution_outbox (aggregate_id);

CREATE INDEX IF NOT EXISTS ix_execution_outbox_created_at ON execution_outbox (created_at);

CREATE INDEX IF NOT EXISTS ix_execution_outbox_dispatch_state ON execution_outbox (dispatch_state);

CREATE INDEX IF NOT EXISTS ix_execution_outbox_kind ON execution_outbox (kind);

CREATE INDEX IF NOT EXISTS ix_execution_outbox_next_attempt_at ON execution_outbox (next_attempt_at);

CREATE TABLE IF NOT EXISTS extracted_fields (
	field_id UUID NOT NULL, 
	parse_run_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	field_key VARCHAR(100) NOT NULL, 
	field_name VARCHAR(200) NOT NULL, 
	field_value TEXT, 
	extraction_method VARCHAR(50) NOT NULL, 
	confidence FLOAT, 
	evidence JSON, 
	data_type VARCHAR(20), 
	unit VARCHAR(50), 
	required BOOLEAN NOT NULL, 
	instances JSON, 
	rule_id UUID, 
	rule_version INTEGER, 
	validation_status VARCHAR(30), 
	extraction_detail JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (field_id)
);

CREATE INDEX IF NOT EXISTS ix_extracted_fields_document_id ON extracted_fields (document_id);

CREATE INDEX IF NOT EXISTS ix_extracted_fields_field_key ON extracted_fields (field_key);

CREATE INDEX IF NOT EXISTS ix_extracted_fields_parse_run_id ON extracted_fields (parse_run_id);

CREATE INDEX IF NOT EXISTS ix_extracted_fields_rule_id ON extracted_fields (rule_id);

CREATE TABLE IF NOT EXISTS extraction_rules (
	rule_id UUID NOT NULL, 
	checklist_type VARCHAR(100) NOT NULL, 
	field_key VARCHAR(100) NOT NULL, 
	field_name_cn VARCHAR(255) NOT NULL, 
	field_description TEXT, 
	dimension_schema JSON NOT NULL, 
	value_kind VARCHAR(30) NOT NULL, 
	data_type VARCHAR(20) NOT NULL, 
	unit VARCHAR(50), 
	required BOOLEAN NOT NULL, 
	multi_instance BOOLEAN NOT NULL, 
	merge_strategy VARCHAR(30) NOT NULL, 
	strategy JSON NOT NULL, 
	validation JSON, 
	fallback_value VARCHAR(255), 
	priority INTEGER NOT NULL, 
	enabled BOOLEAN NOT NULL, 
	version INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (rule_id), 
	CONSTRAINT uq_rule_checklist_field UNIQUE (checklist_type, field_key)
);

CREATE INDEX IF NOT EXISTS ix_extraction_rules_checklist_type ON extraction_rules (checklist_type);

CREATE INDEX IF NOT EXISTS ix_extraction_rules_enabled ON extraction_rules (enabled);

CREATE INDEX IF NOT EXISTS ix_extraction_rules_field_key ON extraction_rules (field_key);

CREATE INDEX IF NOT EXISTS ix_extraction_rules_priority ON extraction_rules (priority);

CREATE TABLE IF NOT EXISTS field_review_revisions (
	review_id UUID NOT NULL, 
	parse_run_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	field_key VARCHAR(100) NOT NULL, 
	revision INTEGER NOT NULL, 
	previous_revision INTEGER NOT NULL, 
	action VARCHAR(20) NOT NULL, 
	reviewer VARCHAR(200) NOT NULL, 
	reason TEXT NOT NULL, 
	file_hash VARCHAR(64) NOT NULL, 
	before_snapshot JSON NOT NULL, 
	facts JSON NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (review_id), 
	CONSTRAINT uq_field_review_revision UNIQUE (parse_run_id, field_key, revision)
);

CREATE INDEX IF NOT EXISTS ix_field_review_revisions_created_at ON field_review_revisions (created_at);

CREATE INDEX IF NOT EXISTS ix_field_review_revisions_document_id ON field_review_revisions (document_id);

CREATE INDEX IF NOT EXISTS ix_field_review_revisions_field_key ON field_review_revisions (field_key);

CREATE INDEX IF NOT EXISTS ix_field_review_revisions_parse_run_id ON field_review_revisions (parse_run_id);

CREATE TABLE IF NOT EXISTS integration_outbox (
	event_id VARCHAR(160) NOT NULL, 
	parse_run_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	payload JSON NOT NULL, 
	destination VARCHAR(1000) NOT NULL, 
	state VARCHAR(30) NOT NULL, 
	attempts INTEGER NOT NULL, 
	max_attempts INTEGER NOT NULL, 
	next_attempt_at TIMESTAMP WITHOUT TIME ZONE, 
	last_error TEXT, 
	acknowledgement JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (event_id)
);

CREATE INDEX IF NOT EXISTS ix_integration_outbox_document_id ON integration_outbox (document_id);

CREATE INDEX IF NOT EXISTS ix_integration_outbox_parse_run_id ON integration_outbox (parse_run_id);

CREATE INDEX IF NOT EXISTS ix_integration_outbox_state ON integration_outbox (state);

CREATE TABLE IF NOT EXISTS integration_requests (
	event_id VARCHAR(160) NOT NULL, 
	document_id UUID NOT NULL, 
	parse_run_id UUID NOT NULL, 
	payload_hash VARCHAR(64) NOT NULL, 
	payload JSON NOT NULL, 
	state VARCHAR(30) NOT NULL, 
	actor VARCHAR(200) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (event_id)
);

CREATE INDEX IF NOT EXISTS ix_integration_requests_document_id ON integration_requests (document_id);

CREATE INDEX IF NOT EXISTS ix_integration_requests_parse_run_id ON integration_requests (parse_run_id);

CREATE TABLE IF NOT EXISTS parse_logs (
	log_id UUID NOT NULL, 
	parse_run_id UUID NOT NULL, 
	level VARCHAR(20) NOT NULL, 
	stage VARCHAR(50) NOT NULL, 
	message TEXT NOT NULL, 
	details JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (log_id)
);

CREATE INDEX IF NOT EXISTS ix_parse_logs_created_at ON parse_logs (created_at);

CREATE INDEX IF NOT EXISTS ix_parse_logs_parse_run_id ON parse_logs (parse_run_id);

CREATE TABLE IF NOT EXISTS rule_bundles (
	bundle_id UUID NOT NULL, 
	checklist_type VARCHAR(100) NOT NULL, 
	version INTEGER NOT NULL, 
	base_generation INTEGER NOT NULL, 
	rules JSON NOT NULL, 
	content_hash VARCHAR(64) NOT NULL, 
	knowledge_hash VARCHAR(64) NOT NULL, 
	note TEXT NOT NULL, 
	operator VARCHAR(100) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (bundle_id), 
	CONSTRAINT uq_bundle_version UNIQUE (checklist_type, version)
);

CREATE INDEX IF NOT EXISTS ix_rule_bundles_checklist_type ON rule_bundles (checklist_type);

CREATE TABLE IF NOT EXISTS rule_change_log (
	log_id UUID NOT NULL, 
	rule_id UUID, 
	checklist_type VARCHAR(100), 
	action VARCHAR(30) NOT NULL, 
	before_state JSON, 
	after_state JSON, 
	operator VARCHAR(100), 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (log_id)
);

CREATE INDEX IF NOT EXISTS ix_rule_change_log_checklist_type ON rule_change_log (checklist_type);

CREATE INDEX IF NOT EXISTS ix_rule_change_log_created_at ON rule_change_log (created_at);

CREATE INDEX IF NOT EXISTS ix_rule_change_log_rule_id ON rule_change_log (rule_id);

CREATE TABLE IF NOT EXISTS source_revisions (
	revision_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	parent_artifact_id UUID NOT NULL, 
	derived_artifact_id UUID, 
	parent_revision_id UUID, 
	revision_type VARCHAR(20) NOT NULL, 
	page_number INTEGER NOT NULL, 
	bbox JSON, 
	start_offset INTEGER, 
	end_offset INTEGER, 
	original_text TEXT, 
	original_text_hash VARCHAR(64), 
	replacement_text TEXT, 
	comment TEXT NOT NULL, 
	affected_fields JSON NOT NULL, 
	source_review_status VARCHAR(30) NOT NULL, 
	extraction_run_id UUID, 
	extraction_task_id VARCHAR(255), 
	created_by VARCHAR(100) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (revision_id)
);

CREATE INDEX IF NOT EXISTS ix_source_revisions_created_at ON source_revisions (created_at);

CREATE INDEX IF NOT EXISTS ix_source_revisions_derived_artifact_id ON source_revisions (derived_artifact_id);

CREATE INDEX IF NOT EXISTS ix_source_revisions_document_id ON source_revisions (document_id);

CREATE INDEX IF NOT EXISTS ix_source_revisions_extraction_run_id ON source_revisions (extraction_run_id);

CREATE INDEX IF NOT EXISTS ix_source_revisions_parent_artifact_id ON source_revisions (parent_artifact_id);

CREATE INDEX IF NOT EXISTS ix_source_revisions_parent_revision_id ON source_revisions (parent_revision_id);

CREATE TABLE IF NOT EXISTS batch_items (
	item_id UUID NOT NULL, 
	batch_id UUID NOT NULL, 
	client_key VARCHAR(200) NOT NULL, 
	file_name VARCHAR(500) NOT NULL, 
	file_hash VARCHAR(64), 
	file_size BIGINT, 
	metadata_json JSON, 
	document_id UUID, 
	parse_run_id UUID, 
	status VARCHAR(30) NOT NULL, 
	attempts INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	error_message TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (item_id), 
	CONSTRAINT uq_batch_item_client_key UNIQUE (batch_id, client_key), 
	FOREIGN KEY(batch_id) REFERENCES batches (batch_id)
);

CREATE INDEX IF NOT EXISTS ix_batch_items_batch_id ON batch_items (batch_id);

CREATE INDEX IF NOT EXISTS ix_batch_items_created_at ON batch_items (created_at);

CREATE INDEX IF NOT EXISTS ix_batch_items_document_id ON batch_items (document_id);

CREATE INDEX IF NOT EXISTS ix_batch_items_file_hash ON batch_items (file_hash);

CREATE INDEX IF NOT EXISTS ix_batch_items_parse_run_id ON batch_items (parse_run_id);

CREATE INDEX IF NOT EXISTS ix_batch_items_status ON batch_items (status);

CREATE TABLE IF NOT EXISTS checklist_release_heads (
	checklist_type VARCHAR(100) NOT NULL, 
	bundle_id UUID NOT NULL, 
	generation INTEGER NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (checklist_type), 
	FOREIGN KEY(bundle_id) REFERENCES rule_bundles (bundle_id)
);

CREATE TABLE IF NOT EXISTS content_invalidations (
	invalidation_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	invalidation_kind VARCHAR(40) NOT NULL, 
	scope_selector JSON NOT NULL, 
	effective_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	reason TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (invalidation_id), 
	FOREIGN KEY(document_id) REFERENCES documents (document_id)
);

CREATE INDEX IF NOT EXISTS ix_content_invalidations_created_at ON content_invalidations (created_at);

CREATE INDEX IF NOT EXISTS ix_content_invalidations_document_id ON content_invalidations (document_id);

CREATE INDEX IF NOT EXISTS ix_content_invalidations_effective_at ON content_invalidations (effective_at);

CREATE INDEX IF NOT EXISTS ix_content_invalidations_invalidation_kind ON content_invalidations (invalidation_kind);

CREATE TABLE IF NOT EXISTS content_revisions (
	revision_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	artifact_id UUID NOT NULL, 
	parent_revision_id UUID, 
	origin_source_revision_id UUID, 
	origin_event_id VARCHAR(200), 
	file_hash VARCHAR(64) NOT NULL, 
	content_digest VARCHAR(64) NOT NULL, 
	preprocess_manifest JSON NOT NULL, 
	adapter_version VARCHAR(80) NOT NULL, 
	source_kind VARCHAR(50) NOT NULL, 
	change_kind VARCHAR(50) NOT NULL, 
	coverage_manifest JSON NOT NULL, 
	coverage_digest VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (revision_id), 
	CONSTRAINT uq_content_revision_source_origin UNIQUE (origin_source_revision_id), 
	FOREIGN KEY(document_id) REFERENCES documents (document_id), 
	FOREIGN KEY(artifact_id) REFERENCES document_artifacts (artifact_id), 
	FOREIGN KEY(parent_revision_id) REFERENCES content_revisions (revision_id), 
	FOREIGN KEY(origin_source_revision_id) REFERENCES source_revisions (revision_id)
);

CREATE INDEX IF NOT EXISTS ix_content_revisions_artifact_id ON content_revisions (artifact_id);

CREATE INDEX IF NOT EXISTS ix_content_revisions_content_digest ON content_revisions (content_digest);

CREATE INDEX IF NOT EXISTS ix_content_revisions_created_at ON content_revisions (created_at);

CREATE INDEX IF NOT EXISTS ix_content_revisions_document_id ON content_revisions (document_id);

CREATE INDEX IF NOT EXISTS ix_content_revisions_file_hash ON content_revisions (file_hash);

CREATE INDEX IF NOT EXISTS ix_content_revisions_origin_event_id ON content_revisions (origin_event_id);

CREATE INDEX IF NOT EXISTS ix_content_revisions_origin_source_revision_id ON content_revisions (origin_source_revision_id);

CREATE INDEX IF NOT EXISTS ix_content_revisions_parent_revision_id ON content_revisions (parent_revision_id);

CREATE TABLE IF NOT EXISTS rule_release_events (
	event_id UUID NOT NULL, 
	checklist_type VARCHAR(100) NOT NULL, 
	bundle_id UUID NOT NULL, 
	previous_bundle_id UUID, 
	action VARCHAR(20) NOT NULL, 
	generation INTEGER NOT NULL, 
	operator VARCHAR(100) NOT NULL, 
	reason TEXT NOT NULL, 
	sample_runs JSON NOT NULL, 
	sample_report JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (event_id), 
	FOREIGN KEY(bundle_id) REFERENCES rule_bundles (bundle_id)
);

CREATE INDEX IF NOT EXISTS ix_rule_release_events_bundle_id ON rule_release_events (bundle_id);

CREATE INDEX IF NOT EXISTS ix_rule_release_events_checklist_type ON rule_release_events (checklist_type);

CREATE INDEX IF NOT EXISTS ix_rule_release_events_created_at ON rule_release_events (created_at);

CREATE TABLE IF NOT EXISTS content_build_jobs (
	build_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	file_hash VARCHAR(64) NOT NULL, 
	profile JSON NOT NULL, 
	parent_revision_id UUID, 
	phase VARCHAR(50) NOT NULL, 
	checkpoint JSON NOT NULL, 
	dispatch_state VARCHAR(32) NOT NULL, 
	attempt INTEGER NOT NULL, 
	lease_owner VARCHAR(200), 
	lease_until TIMESTAMP WITHOUT TIME ZONE, 
	fence_token INTEGER NOT NULL, 
	last_error TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (build_id), 
	CONSTRAINT ck_content_build_counters CHECK (attempt >= 0 AND fence_token >= 0), 
	FOREIGN KEY(document_id) REFERENCES documents (document_id), 
	FOREIGN KEY(parent_revision_id) REFERENCES content_revisions (revision_id)
);

CREATE INDEX IF NOT EXISTS ix_content_build_jobs_created_at ON content_build_jobs (created_at);

CREATE INDEX IF NOT EXISTS ix_content_build_jobs_dispatch_state ON content_build_jobs (dispatch_state);

CREATE INDEX IF NOT EXISTS ix_content_build_jobs_document_id ON content_build_jobs (document_id);

CREATE INDEX IF NOT EXISTS ix_content_build_jobs_file_hash ON content_build_jobs (file_hash);

CREATE INDEX IF NOT EXISTS ix_content_build_jobs_parent_revision_id ON content_build_jobs (parent_revision_id);

CREATE INDEX IF NOT EXISTS ix_content_build_jobs_phase ON content_build_jobs (phase);

CREATE TABLE IF NOT EXISTS content_impacts (
	impact_id UUID NOT NULL, 
	from_revision_id UUID NOT NULL, 
	to_revision_id UUID NOT NULL, 
	changed_ranges JSON NOT NULL, 
	dependency_precision VARCHAR(32) NOT NULL, 
	recompute_policy VARCHAR(32) NOT NULL, 
	invalidation_scope JSON NOT NULL, 
	request_id VARCHAR(200), 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (impact_id), 
	FOREIGN KEY(from_revision_id) REFERENCES content_revisions (revision_id), 
	FOREIGN KEY(to_revision_id) REFERENCES content_revisions (revision_id)
);

CREATE INDEX IF NOT EXISTS ix_content_impacts_created_at ON content_impacts (created_at);

CREATE INDEX IF NOT EXISTS ix_content_impacts_from_revision_id ON content_impacts (from_revision_id);

CREATE INDEX IF NOT EXISTS ix_content_impacts_request_id ON content_impacts (request_id);

CREATE INDEX IF NOT EXISTS ix_content_impacts_to_revision_id ON content_impacts (to_revision_id);

CREATE TABLE IF NOT EXISTS index_generations (
	generation_id UUID NOT NULL, 
	revision_id UUID NOT NULL, 
	config_hash VARCHAR(64) NOT NULL, 
	snapshot_hash VARCHAR(64), 
	build_status VARCHAR(32) NOT NULL, 
	coverage_status VARCHAR(32) NOT NULL, 
	serve_status VARCHAR(32) NOT NULL, 
	serve_version INTEGER NOT NULL, 
	indexed_block_manifest JSON NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (generation_id), 
	CONSTRAINT uq_index_generation_revision_config_snapshot UNIQUE (revision_id, config_hash, snapshot_hash), 
	CONSTRAINT ck_index_generation_serve_status CHECK (serve_status IN ('unavailable','eligible','blocked')), 
	CONSTRAINT ck_index_generation_build_status CHECK (build_status IN ('queued','building','succeeded','failed')), 
	CONSTRAINT ck_index_generation_coverage_status CHECK (coverage_status IN ('unknown','partial','full')), 
	CONSTRAINT ck_index_generation_serve_version CHECK (serve_version >= 0), 
	FOREIGN KEY(revision_id) REFERENCES content_revisions (revision_id)
);

CREATE INDEX IF NOT EXISTS ix_index_generations_build_status ON index_generations (build_status);

CREATE INDEX IF NOT EXISTS ix_index_generations_coverage_status ON index_generations (coverage_status);

CREATE INDEX IF NOT EXISTS ix_index_generations_created_at ON index_generations (created_at);

CREATE INDEX IF NOT EXISTS ix_index_generations_revision_id ON index_generations (revision_id);

CREATE INDEX IF NOT EXISTS ix_index_generations_serve_status ON index_generations (serve_status);

CREATE TABLE IF NOT EXISTS parse_runs (
	parse_run_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	parent_parse_run_id UUID, 
	artifact_id UUID, 
	content_revision_id UUID, 
	contract_version VARCHAR(80), 
	execution_generation INTEGER DEFAULT '0' NOT NULL, 
	requested_field_keys JSON, 
	run_mode VARCHAR(30), 
	checklist_type VARCHAR(100), 
	extraction_profile JSON, 
	status VARCHAR(50) NOT NULL, 
	cache_status VARCHAR(50), 
	fields_extracted INTEGER NOT NULL, 
	mean_confidence FLOAT, 
	started_at TIMESTAMP WITHOUT TIME ZONE, 
	completed_at TIMESTAMP WITHOUT TIME ZONE, 
	duration_seconds FLOAT, 
	quality_status VARCHAR(30), 
	error_message TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (parse_run_id), 
	FOREIGN KEY(content_revision_id) REFERENCES content_revisions (revision_id)
);

CREATE INDEX IF NOT EXISTS ix_parse_runs_artifact_id ON parse_runs (artifact_id);

CREATE INDEX IF NOT EXISTS ix_parse_runs_content_revision_id ON parse_runs (content_revision_id);

CREATE INDEX IF NOT EXISTS ix_parse_runs_contract_version ON parse_runs (contract_version);

CREATE INDEX IF NOT EXISTS ix_parse_runs_created_at ON parse_runs (created_at);

