CREATE TABLE IF NOT EXISTS document_cards (
	card_id UUID NOT NULL, 
	document_id UUID NOT NULL, 
	revision_id UUID NOT NULL, 
	generation_id UUID, 
	status VARCHAR(32) NOT NULL, 
	summary TEXT, 
	outline JSON, 
	risks JSON, 
	citations JSON, 
	error JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (card_id), 
	CONSTRAINT uq_document_card_revision_generation UNIQUE (revision_id, generation_id), 
	FOREIGN KEY(document_id) REFERENCES documents (document_id), 
	FOREIGN KEY(revision_id) REFERENCES content_revisions (revision_id), 
	FOREIGN KEY(generation_id) REFERENCES index_generations (generation_id)
);

CREATE INDEX IF NOT EXISTS ix_document_cards_created_at ON document_cards (created_at);

CREATE INDEX IF NOT EXISTS ix_document_cards_document_id ON document_cards (document_id);

