CREATE OR REPLACE FUNCTION reject_platform_audit_mutation()
RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'field_review_revisions_immutable_audit' AND tgrelid = 'field_review_revisions'::regclass) THEN
CREATE TRIGGER field_review_revisions_immutable_audit BEFORE UPDATE OR DELETE ON field_review_revisions
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'rule_bundles_immutable_audit' AND tgrelid = 'rule_bundles'::regclass) THEN
CREATE TRIGGER rule_bundles_immutable_audit BEFORE UPDATE OR DELETE ON rule_bundles
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'rule_release_events_immutable_audit' AND tgrelid = 'rule_release_events'::regclass) THEN
CREATE TRIGGER rule_release_events_immutable_audit BEFORE UPDATE OR DELETE ON rule_release_events
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'source_revisions_immutable_audit' AND tgrelid = 'source_revisions'::regclass) THEN
CREATE TRIGGER source_revisions_immutable_audit BEFORE UPDATE OR DELETE ON source_revisions
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'content_revisions_immutable_audit' AND tgrelid = 'content_revisions'::regclass) THEN
CREATE TRIGGER content_revisions_immutable_audit BEFORE UPDATE OR DELETE ON content_revisions
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'content_impacts_immutable_audit' AND tgrelid = 'content_impacts'::regclass) THEN
CREATE TRIGGER content_impacts_immutable_audit BEFORE UPDATE OR DELETE ON content_impacts
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'content_invalidations_immutable_audit' AND tgrelid = 'content_invalidations'::regclass) THEN
CREATE TRIGGER content_invalidations_immutable_audit BEFORE UPDATE OR DELETE ON content_invalidations
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

DO $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM pg_trigger
WHERE tgname = 'assistant_feedback_samples_immutable_audit' AND tgrelid = 'assistant_feedback_samples'::regclass) THEN
CREATE TRIGGER assistant_feedback_samples_immutable_audit BEFORE UPDATE OR DELETE ON assistant_feedback_samples
FOR EACH ROW EXECUTE FUNCTION reject_platform_audit_mutation();
END IF; END; $$;

COMMIT;
